import{_ as r,l as s,o as a,c as n,v as i,p as c,x as e,d,i as m,S as l}from"./chunks/framework.InCnrqk-.js";const P=JSON.parse('{"title":"initramfs 与 pivot_root","description":"","frontmatter":{"title":"initramfs 与 pivot_root","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/initramfs-pivot.md","filePath":"cs/initramfs-pivot.md","lastUpdated":1789023840000}'),p={name:"cs/initramfs-pivot.md"};function f(_,t,h,u,v,A){const o=s("Mermaid");return a(),n("div",null,[t[1]||(t[1]=i('<h1 id="initramfs-与-pivot-root" tabindex="-1">initramfs 与 pivot_root <a class="header-anchor" href="#initramfs-与-pivot-root" aria-label="Permalink to &quot;initramfs 与 pivot_root&quot;">​</a></h1><div class="epigraph"><p>initramfs 是内核解开的内存根：里面的脚本开 [dm-crypt](/cs/dm-crypt)、组 [RAID](/cs/md-raid)、加载驱动，再 pivot_root 到真正的磁盘根。</p><footer>—— 据 Linux initrd/initramfs 文档；pivot_root(2)；[tmpfs](/cs/tmpfs) 为内存树先修</footer></div><p><a href="/cs/tpm-measured-boot">TPM</a> 可能在这一阶段解封。<a href="/cs/device-nodes">设备节点</a> 需要驱动。缺口是 <strong>早期用户空间</strong> 与切换根，不是 systemd 全部。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>内核不能把所有磁盘/LVM/网络模块编进镜像。initramfs：cpio 进 RAM，<code>/init</code> 跑。缺口：<code>switch_root</code>/<code>pivot_root</code> 把旧根丢掉或移走，避免占用；与 <a href="/cs/overlayfs">overlay</a> 做运行时根。本课不把 dracut 模块列表抄完。</p><p><span class="marginnote">initrd 是旧块设备形式。今日多为 initramfs。紧急壳在此阶段常见。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>内核挂载 ramfs → exec <code>/init</code> → 组装 <code>/dev</code>、解密、fsck → pivot 到 <code>/newroot</code>。对照 <a href="/cs/fuse">FUSE</a>：此时通常还没有。对照 <a href="/cs/nfs-semantics">NFS</a> 根：init 要先有网卡。对照 kexec：另一条启动，不在本课。</p>',8)),(a(),c(l,null,{default:e(()=>[m(o,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20K%5B%22%E5%86%85%E6%A0%B8%22%5D%20--%3E%20IR%5B%22initramfs%20%2Finit%22%5D%0A%20%20IR%20--%3E%20SETUP%5B%22%E9%A9%B1%E5%8A%A8%E4%B8%8E%E8%A7%A3%E5%AF%86%22%5D%0A%20%20SETUP%20--%3E%20PV%5B%22pivot_root%22%5D%0A%20%20PV%20--%3E%20REAL%5B%22%E7%A3%81%E7%9B%98%E4%B8%8A%E7%9A%84%20%2Fsbin%2Finit%22%5D%0A"})]),fallback:e(()=>[...t[0]||(t[0]=[d(" Loading... ",-1)])]),_:1})),t[2]||(t[2]=i('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>initramfs 把「内核太早、根还不可用」收成用户态程序，使复杂存储栈可启动。它是信任链的一环：未签名的 initramfs 可偷密钥。不要写成发行版安装器。与 <a href="/cs/memcg">memcg</a>：此阶段通常无 cgroup 限制。</p><p>失败：掉进 emergency shell，对象仍是这棵内存树。</p><p>实现上：initramfs 里的密钥提示是攻击面，TPM 解封应在此阶段。pivot 后要 umount 旧根，否则 ramfs 占着内存。emergency shell 仍是这棵树，网络可能还没有。 读法上只引用<a href="/cs/tpm-measured-boot">上一课</a>的结论，不把对象换成训练推理或限价簿。</p><p>本课在操作系统进阶的「安全、启动与调试 / 内核安全与启动」课序里，对象是 <strong>initramfs 与 pivot_root</strong>。</p><ul><li>先修只引用，不重导：上一课的结论当公理，本课只补差。</li><li>五栏不吞并：不把本课写成大模型训练/推理，也不写成限价簿或权重量化。</li><li>文献用 OSTEP、McKusick、内核文档与具名会议论文；不发明 arXiv 编号。</li></ul><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入所有 resume from hibernate 细节——挂起后课。不保证嵌入式无 initramfs。下一课真正的 PID 1：systemd 单元。</p><p>版本字段会变，课序钉的是机制对象「initramfs 与 pivot_root」，不是某一主线内核的结构体名。 后课默认：磁盘根经 pivot 接上。systemd 单元与依赖，下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>initramfs 在内存里准备真根。</li><li>pivot_root 切换，旧 ram 根释放。</li><li>systemd 单元是下一课。</li><li>出处：Linux initramfs；<code>pivot_root(2)</code>；dracut。</li></ul>',11))])}const T=r(p,[["render",f]]);export{P as __pageData,T as default};
